'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=u=>{try{const p=new URL(u);return ['https:','http:'].includes(p.protocol)&&!p.username&&!p.password&&!/(^|\.)synsig\.org$/i.test(p.hostname)?p.href:null}catch{return null}};
const link=(u,t)=>safe(u)?`<a href="${esc(safe(u))}" target="_blank" rel="noopener noreferrer">${esc(t)}<span class="sr-only"> (opens in a new tab)</span></a>`:esc(t);
const links=xs=>`<div class="links">${(xs||[]).map(x=>link(x.href,x.label)).join('')}</div>`;
let data, filter='all', query='';
/* Anywhere-on-Earth date: an event leaves "Upcoming" only after its date has ended in every timezone. */
const today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Etc/GMT+12',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day};
const fmt=d=>{if(!d)return 'Not yet checked';const t=new Date(/^\d{4}-\d{2}-\d{2}$/.test(d)?d+'T12:00:00Z':d);return Number.isNaN(t.getTime())?String(d):new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Taipei'}).format(t)};
const intro=(n,title,text)=>`<p class="section-label">${esc(n)} / ISCA SPECIAL INTEREST GROUPS</p><h1>${esc(title)}</h1><p class="intro">${esc(text)}</p>`;
function sourceCheck(url){const s=data.checks.sources.find(s=>s.url===url);return s?`<span class="check ${s.status==='retrieved'?'':'warning'}">${s.status==='retrieved'?'Source page retrieved':'Source could not be retrieved'} · ${esc(fmt(s.checkedAt))}</span>`:''}
function sigHTML(s){s={activities:[],series:[],videos:[],...s};return `<details class="sig" id="sig-${esc(s.acronym)}"><summary class="sig-summary-row"><span class="sig-code">${esc(s.acronym)}<span class="sig-kind">${s.kind==='language'?'Language SIG':'Topic SIG'}</span></span><h2 class="sig-name">${esc(s.fullName)}</h2><span class="sig-summary" aria-hidden="true">${esc(s.summary||s.description)}</span><span class="sig-meta"><span>${s.activities.length} activities<br>${s.videos.length?s.videos.length+' recording links':'No recordings located'}</span><span class="expand-label" aria-hidden="true"></span></span></summary><div class="sig-body"><p>${esc(s.description)}</p><div class="links">${s.website?link(s.website,'SIG website'):''}${link(s.iscaUrl,'Official ISCA profile')}</div>${sourceCheck(s.website||s.iscaUrl)}<p class="source-line">${s.contentReviewed?`Profile reviewed: ${esc(fmt(s.contentReviewed))}; first compiled ${esc(fmt(data.generated))}.`:`Profile first compiled: ${esc(fmt(data.generated))}.`} Source retrieval dates do not certify every detail.</p><h3>Activities & recurring events</h3>${s.activities.map(a=>`<div class="activity"><div class="activity-title">${a.url?link(a.url,a.name):esc(a.name)}</div>${a.cadence?`<p>${esc(a.cadence)}</p>`:''}${a.last?`<p>${esc(a.last)}</p>`:''}</div>`).join('')}${s.series.length?`<h3>Seminars & lecture series</h3>${s.series.map(w=>`<div class="activity"><div class="activity-title">${link(w.pageUrl,w.name)}</div><p>${esc(w.cadence||'Schedule announced by the organizer')}</p><p>${esc(w.notes)}</p>${w.recUrl?link(w.recUrl,'Recording index'):''}</div>`).join('')}`:''}<h3>Recordings & video resources</h3>${s.videos.length?s.videos.map(v=>`<div class="activity"><div class="activity-title">${link(v.url,v.title)}</div><p>${esc(v.what)}</p></div>`).join(''):'<p>No public recording link has been located in this directory. This does not establish that none exists.</p>'}<div class="links"><a href="mailto:speechlab0210@gmail.com?subject=${encodeURIComponent('[ISCA SIG Atlas] '+s.acronym+' correction')}">Suggest a correction for ${esc(s.acronym)}</a><a href="#sig-${esc(s.acronym)}">Link to this SIG</a></div></div></details>`}
function directory(){return intro('01','Find your speech community.','Workshops, conversations and recordings across ISCA’s specialist groups. Open a group to explore its activities and original sources.')+`<div class="stats"><span><b>${data.sigs.length}</b>SIGs</span><span><b>${data.editorial.series.length}</b>series & courses</span><span><b>${data.sigs.reduce((n,s)=>n+s.videos.length,0)}</b>recording links</span></div><div class="toolbar"><div class="search-wrap"><label for="search">Search groups, topics, workshops or recordings</label><input type="search" id="search" placeholder="Try prosody, synthesis, dialogue…" value="${esc(query)}"></div></div><div class="filters" role="group" aria-label="Filter SIGs">${[['all','All groups'],['topic','Topic SIGs'],['language','Language SIGs'],['recordings','With recordings']].map(([id,l])=>`<button class="filter" data-filter="${id}" aria-pressed="${filter===id}">${l}</button>`).join('')}</div><div class="result-count" role="status" id="count"></div><div class="table-header"><span>GROUP</span><span>FIELD & FOCUS</span><span>IN THE INDEX</span></div><div id="sig-list"></div><p class="source-line">${link('https://isca-speech.org/Special-Interest-Groups','Official ISCA group list')} · Last source check: ${esc(fmt(data.checks.checkedAt))} · <a href="#about">Coverage & review dates</a></p>`}
const searchText=s=>[s.acronym,s.fullName,s.kind==='language'?'Language SIG':'Topic SIG',s.description,...s.activities.flatMap(a=>[a.name,a.type&&a.type.replace(/-/g,' '),a.cadence,a.last]),...(s.series||[]).flatMap(w=>[w.name,w.cadence,w.notes]),...s.videos.flatMap(v=>[v.title,v.kind&&v.kind.replace(/-/g,' '),v.what])].filter(Boolean).join(' ').toLocaleLowerCase();
function filterList(){const q=query.trim().toLocaleLowerCase();const rows=data.sigs.filter(s=>(filter==='all'||s.kind===filter||filter==='recordings'&&s.videos.length>0)&&searchText(s).includes(q));$('#sig-list').innerHTML=rows.map(sigHTML).join('')||'<p class="empty">No matching group. Try a broader topic or choose All groups.</p>';$('#count').textContent=`${rows.length} of ${data.sigs.length} groups`;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)))}
function series(){return intro('02','Listen in. Keep learning.','Seminar indexes, lecture series and recording collections maintained by the speech community.')+`<p class="notice">Series status is dated, not a promise of the next session. Follow the organizer’s page for registration and any schedule changes.</p>`+data.editorial.series.map(s=>`<article class="series-row"><div class="series-code">${esc(s.sig)}<br><span class="tag">${esc(({live:'Series listed',paused:'Archive',announced:'Announced'})[s.pill]||s.pill)}</span></div><div><h2>${esc(s.name)}</h2><p class="cadence">${esc(s.cad)}</p><p>${esc(s.text)}</p>${s.next?`<p>${esc(s.next)}</p>`:''}${links(s.links)}<p class="source-line">Content review: ${esc(fmt(s.reviewed||data.generated))}</p></div></article>`).join('')+`<h2>Workshop & conference recordings</h2><p class="intro">Full sessions, keynotes and tutorials from individual event editions. Older hosts may be unavailable.</p><div class="archive-grid">${data.editorial.archives.map(r=>`<article class="resource"><span class="eyebrow">${esc(r.sig)}</span><h3>${esc(r.name)}</h3>${links(r.links)}</article>`).join('')}</div>`}
function eventRow(e){return `<article class="event-row"><time class="event-date" datetime="${esc(e.start)}">${esc(e.displayDate||fmt(e.start))}</time><div><span class="eyebrow">${esc(e.sig)}</span><h3>${link(e.url,e.title)}</h3>${e.details?`<p>${esc(e.details)}</p>`:''}<p class="source-line">${e.verified?'Source reviewed':'Not fully confirmed; reconfirm before making plans'} · ${esc(fmt(e.reviewed))}</p></div></article>`}
function events(){const now=today(), sorted=[...data.events].sort((a,b)=>a.start.localeCompare(b.start));const future=sorted.filter(e=>(e.end||e.start)>=now),past=sorted.filter(e=>(e.end||e.start)<now).reverse();return intro('03','On the calendar.','Upcoming talks and specialist meetings, with dates and source pages. All times retain the organizer’s stated timezone.')+`<h2>Upcoming & in progress <span class="tag">${future.length}</span></h2>${future.length?future.map(eventRow).join(''):'<p class="empty">No upcoming event has been confirmed in the current index. Check the individual SIG pages for announcements.</p>'}<h2>Recently past</h2><p class="intro">Past dates move here automatically. A passed date does not confirm that an event took place.</p>${past.map(eventRow).join('')}`}
function resources(){return intro('04','The wider ISCA library.','Association-level places to find lectures, papers, training material and conversations.')+data.editorial.central.map(r=>`<article class="resource"><h2>${r.url?link(r.url,r.name):esc(r.name)}</h2><p>${esc(r.what)}</p>${links(r.links)}${r.url?sourceCheck(r.url):''}</article>`).join('')+`<p class="source-line">Inherited resource descriptions: ${esc(fmt(data.generated))}; follow original sources for the current extent of each collection.</p>`}
function about(){const sources=data.checks.sources,ok=sources.filter(s=>s.status==='retrieved').length;return intro('05','A directory with a paper trail.','Built from public primary sources. Maintained by Xiaojin, an AI agent; independent of ISCA and not certified by human reviewers.')+`<div class="method-grid"><section><h2>What is included</h2><p>The directory retains the ${data.sigs.length} SIG profiles and their activities, seminar series and recording links collected for SCOOT 2.0. Since 3 October 2026, ${link('https://speechlab0210.github.io/scoot/','SCOOT 2.0')} covers learning resources only and links here for SIG content.</p><p>${link('https://isca-speech.org/Special-Interest-Groups','The official ISCA roster')} defines the group list. Former groups SALTMIL and SLIM are historical entries on that roster and are outside this set.</p><p>The collection was first compiled on ${esc(fmt(data.generated))}. Each profile and event shows the date it was last reviewed against its sources. An accessible source page is not the same as a fully reverified profile.</p></section><section><h2>Corrections welcome</h2><p>Send missing resources, revised dates, broken links or suggestions to <a href="mailto:speechlab0210@gmail.com?subject=%5BISCA%20SIG%20Atlas%5D%20Suggestion">speechlab0210@gmail.com</a>.</p><p>Please include the SIG name, what should change, and an official source. Mail is checked three times a day. Small, verifiable corrections are applied directly, and the sender receives a reply describing the change. Changes requested by members of the ISCA Board, whose identity is checked against the Board list on isca-speech.org, are applied; requests outside the scope of this directory are referred to the site’s human supervisor. Anything that needs a decision is forwarded privately to the site’s human supervisor.</p><p>Corrections are handled by email only. Messages and sender details are not published, and replies are copied to the human supervisor.</p></section></div><h2>How this directory is maintained</h2><div class="status-summary">Last source check: <b>${esc(fmt(data.checks.checkedAt))}</b><br>${ok===sources.length?`All ${sources.length} source pages were retrieved.`:`${ok} of ${sources.length} source pages retrieved; ${sources.length-ok} could not be retrieved in that check.`}</div><ol class="method-steps"><li><b>Every day</b>, the official ISCA SIG list, each SIG’s website (or its ISCA page where it has none), the seminar indexes, the activity and event pages cited here and the association resources are collected again (${sources.length} pages in the latest check). Video platforms and pages that need a login are not collected.</li><li>Pages that changed since the last review are compared line by line. Updates found this way are published only when they are confirmed on a first-party source (the SIG’s own site, isca-speech.org or the event’s own site), and dates are read from the source page itself.</li><li>Each day a few SIGs also get a targeted search for new workshops, seminars and recordings, rotating through all the groups in turn.</li><li>A page that cannot be reached keeps its previous information; a failed check is not treated as a sign that an activity stopped. Past dates move to “Recently past” automatically, and a passed date does not confirm that an event took place.</li><li>Larger changes found this way, such as adding or removing a group or a resource, restructuring the directory or settling conflicting sources, are referred to the site’s human supervisor instead of being made automatically.</li><li>Each published update is summarised in the update log below.</li></ol><p>Registration pages remain authoritative for dates, timezones and access. Recording links point to external hosts; this site does not copy or host the videos.</p><p class="notice">Do not use the historical synsig.org address. The original investigation found it had changed to unrelated content. Use the SynSIG pages on isca-speech.org.</p><h2>Update log</h2>${data.updates.map(u=>`<div class="update-row"><time datetime="${esc(u.date)}">${esc(fmt(u.date))}</time><p>${esc(u.text)}</p></div>`).join('')}<details><summary>Source check results (${sources.length})</summary><ul class="source-list">${sources.map(s=>`<li>${link(s.url,(s.groups||[]).join(' · ')||s.url)} — ${s.status==='retrieved'?'page retrieved':'unavailable on this check'}<br><small>${esc(s.url)}</small></li>`).join('')}</ul></details><h2>Research notes</h2><p class="source-line">Observations first recorded on 31 August 2026 and last rechecked on ${esc(fmt(data.editorial.notesReviewed||'2026-10-03'))}. They describe what was found on those dates, not a promise that every condition still holds.</p><ul class="notes">${(data.editorial.notes||[]).map(n=>`<li>${esc(n.text)}</li>`).join('')}</ul>`}
function render(){let hash='';try{hash=decodeURIComponent(location.hash.slice(1))}catch{}if(hash==='main'&&$('#content h1'))return;if(hash.startsWith('sig-')&&!document.getElementById(hash)){filter='all';query=''}const section=hash.startsWith('sig-')?'directory':['directory','series','events','resources','about'].includes(hash)?hash:'directory';$('#content').innerHTML=({directory,series,events,resources,about})[section]();document.querySelectorAll('[data-section]').forEach(a=>{if(a.dataset.section===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(section==='directory'){filterList();$('#search').addEventListener('input',e=>{query=e.target.value;filterList()});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;filterList()}));if(hash.startsWith('sig-')){const row=document.getElementById(hash);if(row){row.open=true;const go=()=>row.scrollIntoView({block:'start'});go();if(document.fonts)document.fonts.ready.then(go);row.querySelector('summary').focus({preventScroll:true})}}}document.title=({directory:'Groups',series:'Seminars & recordings',events:'Events',resources:'Resources',about:'Sources & updates'})[section]+' · ISCA SIG Atlas'}
fetch('data.json').then(r=>{if(!r.ok)throw Error('data unavailable');return r.json()}).then(d=>{data=d;render();window.addEventListener('hashchange',()=>{render();if(/^#(sig-|main$)/.test(location.hash))return;window.scrollTo({top:0});const h=$('#content h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}})}).catch(()=>{$('#content').innerHTML='<div class="error"><h1>The directory could not load.</h1><p>Please refresh the page, or contact <a href="mailto:speechlab0210@gmail.com">speechlab0210@gmail.com</a>.</p></div>'});
